import React from 'react';
import { useTheme } from '../../contexts/ThemeContext';

function Todo() {
    const { theme } = useTheme();
    return (
        <div className={`page-content ${theme}`}>
            <h2>Список Завдань (Todo)</h2>
            <p>Тут буде розміщено функціонал списку завдань (Todo List).</p>
            <p>Слідкуйте за оновленнями!</p>
        </div>
    );
}

export default Todo;
